        },
        "instructions": {
          "description": "What is being rated. The answer is a probability-weighted position on the rubric; it collapses to the most likely integer level under the question name.",
          "title": "Instructions",
          "type": "string"
        },
        "criteria": {
          "description": "Ordered rubric, lowest level first. Level numbers are the list positions starting at 0.",
          "items": {
            "type": "string"
          },
          "maxItems": 10,
          "minItems": 2,
          "title": "Criteria",
          "type": "array"
